/**
 * The contract `item.tsx` (native) and `item.web.tsx` (web) both implement: shadcn's `Item` parts,
 * with the part of each one's classes that Yoga can read. Its own module because Metro resolves
 * `./item` to `item.web.tsx` on web.
 *
 * Each class here is what the two halves agree on; the web half adds what only the DOM has —
 * `group-has-[…]`, `[&_svg]`, `[a]:`, the focus ring, `text-balance` — and the native half adds a
 * `Text` around a string and the ink a `Text` does not inherit there. The metrics are shadcn's,
 * so a row drawn with these parts on a device lines up with the same row in a DOM app.
 */
import { cva } from "class-variance-authority";

export type ItemVariant = "default" | "outline" | "muted";
export type ItemSize = "default" | "sm";
export type ItemMediaVariant = "default" | "icon" | "image";

/**
 * The row: its children side by side, wrapping — `ItemHeader` and `ItemFooter` take a line of their
 * own. `outline` is the bordered card-per-row, `muted` a filled one.
 */
export const itemVariants = cva(
  "flex-row flex-wrap items-center rounded-md border border-transparent",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline: "border-border",
        muted: "bg-muted/50",
      },
      size: {
        default: "gap-4 p-4",
        sm: "gap-2.5 px-4 py-3",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);

/**
 * The start of the row: an icon in a small tile, an image, or whatever is passed. On the web an
 * `<svg>` or `<img>` inside is sized for you; on a device pass it sized (`size-4`, `size-full`).
 */
export const itemMediaVariants = cva("shrink-0 flex-row items-center justify-center gap-2", {
  variants: {
    variant: {
      default: "bg-transparent",
      icon: "size-8 rounded-sm border border-border bg-muted",
      image: "size-10 overflow-hidden rounded-sm",
    },
  },
  defaultVariants: { variant: "default" },
});

/** The middle: the title over the description, taking the row's spare width. */
export const ITEM_CONTENT_CLASS = "flex-1 gap-1";

/** The title's line: text, a badge beside it, side by side. */
export const ITEM_TITLE_CLASS = "flex-row items-center gap-2";

/** The title's type. On a device it goes on the `Text` a string is wrapped in, with its ink. */
export const ITEM_TITLE_TEXT = "text-sm leading-snug font-medium";

/** The muted line under the title, two lines at most. */
export const ITEM_DESCRIPTION_CLASS =
  "line-clamp-2 text-sm leading-normal font-normal text-muted-foreground";

/** The far end: buttons, a menu. */
export const ITEM_ACTIONS_CLASS = "flex-row items-center gap-2";

/** A full-width line above the rest of the row. */
export const ITEM_HEADER_CLASS = "flex-row items-center justify-between gap-2";

/** A full-width line below the rest of the row. */
export const ITEM_FOOTER_CLASS = "flex-row items-center justify-between gap-2";

/** The rule between rows in an `ItemGroup`. */
export const ITEM_SEPARATOR_CLASS = "my-0 shrink-0 bg-border";

/**
 * shadcn's `Item` parts on React Native: `Item`, `ItemMedia`, `ItemContent`, `ItemTitle`,
 * `ItemDescription`, `ItemActions`, `ItemHeader`, `ItemFooter`, `ItemGroup` and `ItemSeparator`,
 * under shadcn's names and with its `variant` and `size`. `item.web.tsx` is the web counterpart
 * and `item-base.ts` holds the classes the two share, so a row composed from these parts in an
 * Expo app is the row a DOM app draws from the same call site.
 *
 * The parts are the regions `ListItem` places, named the other way round: `ItemMedia` is its
 * `leading`, `ItemContent` its middle, `ItemTitle` and `ItemDescription` its title and the line
 * under it, `ItemActions` its `action`. `ListItem` is the row with those decisions made — one line
 * of title, the pressed area in the middle only. These are for a row it does not fit: a header
 * line, a footer that opens, a title with a badge beside it. It is what `DisclosureRow` is made of.
 *
 * What differs on a device, none of it a call-site change:
 *
 * - A string passed to a part is wrapped in a `Text` for you — a bare string in a `View` throws
 *   there — and that `Text` carries the part's type and ink, because nothing inherits on native.
 *   An element you pass (a `Badge`, an icon) is placed as it is.
 * - `ItemMedia` does not size what is in it: there is no `[&_svg]` selector. Pass an icon at
 *   `size-4`, an image at `size-full`. Nor does it move to the top of a row with a description,
 *   which shadcn does with `:has()`; it stays centred, and `className="self-start"` lifts it.
 * - `asChild` is radix's `Slot`, as `Button`'s is: `<Item asChild><Pressable onPress={open}>…`
 *   makes the whole row the pressable. On the web it is shadcn's, onto an `<a>` or a `<button>`.
 * - `ItemSeparator` is a hairline `View`; it takes `orientation` and `decorative` so a shadcn call
 *   site still typechecks, and draws a vertical rule for `orientation="vertical"`.
 */
import { Slot } from "radix-ui";
import * as React from "react";
import { Text, View } from "react-native";
import {
  ITEM_ACTIONS_CLASS,
  ITEM_CONTENT_CLASS,
  ITEM_DESCRIPTION_CLASS,
  ITEM_FOOTER_CLASS,
  ITEM_HEADER_CLASS,
  ITEM_SEPARATOR_CLASS,
  ITEM_TITLE_CLASS,
  ITEM_TITLE_TEXT,
  type ItemMediaVariant,
  type ItemSize,
  type ItemVariant,
  itemMediaVariants,
  itemVariants,
} from "@/components/ui/item-base";
import { cn } from "@/lib/utils";

// `className` is re-declared rather than inherited: nativewind types it as `className?: string`,
// which under `exactOptionalPropertyTypes` rejects the conditional a call site passes.
type ViewProps = Omit<React.ComponentProps<typeof View>, "className"> & {
  className?: string | undefined;
};
type TextProps = Omit<React.ComponentProps<typeof Text>, "className"> & {
  className?: string | undefined;
};

/** The ink and type a string in a part is drawn with, where nothing is inherited. */
const PART_TEXT = "text-foreground text-sm";

/**
 * Each string or number child in its own `Text`, elements left as they are. A part holds a badge
 * beside a word as often as a word alone, so it is the children one by one, not all or nothing.
 */
function withText(children: React.ReactNode, className: string) {
  return React.Children.map(children, (child) =>
    typeof child === "string" || typeof child === "number" ? (
      <Text className={className}>{child}</Text>
    ) : (
      child
    ),
  );
}

function ItemGroup({ className, ...props }: ViewProps) {
  return <View testID="item-group" className={cn("flex-col", className)} {...props} />;
}

type ItemSeparatorProps = Omit<ViewProps, "children"> & {
  orientation?: "horizontal" | "vertical" | undefined;
  /**
   * shadcn's: a decorative rule is hidden from assistive technology, which is the default. `false`
   * announces it as a separator between the rows either side.
   */
  decorative?: boolean | undefined;
};

function ItemSeparator({
  className,
  orientation = "horizontal",
  decorative = true,
  ...props
}: ItemSeparatorProps) {
  return (
    <View
      testID="item-separator"
      {...(decorative ? { "aria-hidden": true } : { role: "separator" as const })}
      className={cn(
        ITEM_SEPARATOR_CLASS,
        orientation === "vertical" ? "h-full w-px" : "h-px w-full",
        className,
      )}
      {...props}
    />
  );
}

type ItemProps = ViewProps & {
  variant?: ItemVariant | null | undefined;
  size?: ItemSize | null | undefined;
  /**
   * Hand the row's classes to the one child instead of a `View` around it — a `Pressable` that
   * opens the record, an expo-router `Link`. Radix's `Slot`, as on `Button`.
   */
  asChild?: boolean | undefined;
};

function Item({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: ItemProps) {
  const classes = cn(itemVariants({ variant, size }), className);
  if (asChild) {
    // `Slot.Root` is typed for the DOM, but it renders nothing of its own — it clones the caller's
    // one child with these props merged in — so the cast is the honest way to say neither side's
    // typing describes it (`Button` does the same).
    return (
      <Slot.Root className={classes} {...(props as unknown as React.HTMLAttributes<HTMLElement>)} />
    );
  }
  return <View testID="item" className={classes} {...props} />;
}

type ItemMediaProps = ViewProps & { variant?: ItemMediaVariant | null | undefined };

function ItemMedia({ className, variant = "default", ...props }: ItemMediaProps) {
  return (
    <View
      testID="item-media"
      className={cn(itemMediaVariants({ variant }), className)}
      {...props}
    />
  );
}

function ItemContent({ className, children, ...props }: ViewProps) {
  return (
    <View testID="item-content" className={cn(ITEM_CONTENT_CLASS, className)} {...props}>
      {withText(children, PART_TEXT)}
    </View>
  );
}

/**
 * A `View` holding the line, not a `Text`, because the line is as often a badge beside a word as a
 * word — and a `View` inside a `Text` is not a row on a device. The string gets the title's type.
 */
function ItemTitle({ className, children, ...props }: ViewProps) {
  return (
    <View testID="item-title" className={cn("self-start", ITEM_TITLE_CLASS, className)} {...props}>
      {withText(children, cn("text-foreground", ITEM_TITLE_TEXT))}
    </View>
  );
}

function ItemDescription({ className, ...props }: TextProps) {
  return (
    <Text testID="item-description" className={cn(ITEM_DESCRIPTION_CLASS, className)} {...props} />
  );
}

function ItemActions({ className, children, ...props }: ViewProps) {
  return (
    <View testID="item-actions" className={cn(ITEM_ACTIONS_CLASS, className)} {...props}>
      {withText(children, PART_TEXT)}
    </View>
  );
}

function ItemHeader({ className, children, ...props }: ViewProps) {
  return (
    <View testID="item-header" className={cn("w-full", ITEM_HEADER_CLASS, className)} {...props}>
      {withText(children, PART_TEXT)}
    </View>
  );
}

function ItemFooter({ className, children, ...props }: ViewProps) {
  return (
    <View testID="item-footer" className={cn("w-full", ITEM_FOOTER_CLASS, className)} {...props}>
      {withText(children, PART_TEXT)}
    </View>
  );
}

export {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemFooter,
  ItemGroup,
  ItemHeader,
  ItemMedia,
  ItemSeparator,
  ItemTitle,
};

/**
 * The web `Item`: shadcn's parts, with shadcn's props and markup, so a DOM call site that installed
 * `@cubeui/item` before it had a native half compiles and draws as it did. `item.tsx` is the
 * native counterpart and `item-base.ts` holds the classes the two share; what is added here is
 * what only the DOM has.
 *
 * It is hand-written rather than compiled for three reasons the compiler would have to guess at:
 * `ItemDescription` is shadcn's `<p>` taking `<p>` props, `ItemSeparator` is radix's, and the
 * compiled reset (`flex-shrink: 0` on every view) would stop a long title shrinking inside a row
 * that shadcn lets shrink — the thing `DisclosureRow`'s truncating title depends on.
 *
 * `ItemSeparator` is radix's `Separator` directly, with the classes shadcn's `Separator` gives it,
 * rather than `@cubeui/separator`: that one is web-only, and the native registry installs this file
 * beside `item.tsx`, where an import of it would point at nothing.
 */
import type { VariantProps } from "class-variance-authority";
import { Separator as SeparatorPrimitive, Slot } from "radix-ui";
import type * as React from "react";
import {
  ITEM_ACTIONS_CLASS,
  ITEM_CONTENT_CLASS,
  ITEM_DESCRIPTION_CLASS,
  ITEM_FOOTER_CLASS,
  ITEM_HEADER_CLASS,
  ITEM_SEPARATOR_CLASS,
  ITEM_TITLE_CLASS,
  ITEM_TITLE_TEXT,
  itemMediaVariants,
  itemVariants,
} from "@/components/ui/item-base";
import { cn } from "@/lib/utils";

/**
 * Upstream ships this with `role="list"`, and it is dropped here on purpose: nothing in this
 * file can be the `listitem` that role requires. `Item` takes `asChild`, so a caller may render
 * it as an `<a>` or a `<button>`, and a fixed role here would clobber that one — which is why
 * upstream does not put it there either. A `list` owning no `listitem` is not a neutral
 * overclaim: it announces as an empty list, and an AT that exposes only listitem children hides
 * whatever is inside it. A caller that really is drawing a list can say so on its own wrapper,
 * which is also where it owns the items.
 */
function ItemGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-group"
      className={cn("group/item-group flex flex-col", className)}
      {...props}
    />
  );
}

function ItemSeparator({
  className,
  orientation = "horizontal",
  decorative = true,
  ...props
}: React.ComponentProps<typeof SeparatorPrimitive.Root>) {
  return (
    <SeparatorPrimitive.Root
      data-slot="item-separator"
      decorative={decorative}
      orientation={orientation}
      className={cn(
        ITEM_SEPARATOR_CLASS,
        "data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-full data-[orientation=vertical]:w-px",
        className,
      )}
      {...props}
    />
  );
}

/** What only a DOM row has: the hover on a link row, and the focus ring. */
const ITEM_WEB =
  "group/item flex text-sm transition-colors duration-100 outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 [a]:transition-colors [a]:hover:bg-accent/50";

function Item({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof itemVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "div";
  return (
    <Comp
      data-slot="item"
      data-variant={variant}
      data-size={size}
      className={cn(ITEM_WEB, itemVariants({ variant, size }), className)}
      {...props}
    />
  );
}

/** Sizing what is inside, which a device cannot select for, and the nudge beside a description. */
const ITEM_MEDIA_WEB = {
  default: "",
  icon: "[&_svg:not([class*='size-'])]:size-4",
  image: "[&_img]:size-full [&_img]:object-cover",
} as const;

function ItemMedia({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof itemMediaVariants>) {
  return (
    <div
      data-slot="item-media"
      data-variant={variant}
      className={cn(
        "flex group-has-[[data-slot=item-description]]/item:translate-y-0.5 group-has-[[data-slot=item-description]]/item:self-start [&_svg]:pointer-events-none",
        itemMediaVariants({ variant }),
        ITEM_MEDIA_WEB[variant ?? "default"],
        className,
      )}
      {...props}
    />
  );
}

function ItemContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-content"
      className={cn(
        "flex flex-col [&+[data-slot=item-content]]:flex-none",
        ITEM_CONTENT_CLASS,
        className,
      )}
      {...props}
    />
  );
}

function ItemTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-title"
      className={cn("flex w-fit", ITEM_TITLE_CLASS, ITEM_TITLE_TEXT, className)}
      {...props}
    />
  );
}

function ItemDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="item-description"
      className={cn(
        ITEM_DESCRIPTION_CLASS,
        "text-balance [&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        className,
      )}
      {...props}
    />
  );
}

function ItemActions({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-actions"
      className={cn("flex", ITEM_ACTIONS_CLASS, className)}
      {...props}
    />
  );
}

function ItemHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-header"
      className={cn("flex basis-full", ITEM_HEADER_CLASS, className)}
      {...props}
    />
  );
}

function ItemFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="item-footer"
      className={cn("flex basis-full", ITEM_FOOTER_CLASS, className)}
      {...props}
    />
  );
}

export {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemFooter,
  ItemGroup,
  ItemHeader,
  ItemMedia,
  ItemSeparator,
  ItemTitle,
};
